// Fighters for the fight engine: the player built from the save, AI opponents generated by belt.
import { BELTS, MOVES } from '../data/moves.js';
import { effectiveLevel } from './progression.js';
import { pick } from './rng.js';

const NAMES = ['Marko', 'Ivan', 'Luka', 'Petar', 'Ante', 'Josip', 'Matej', 'Filip', 'Dino', 'Tomislav', 'Karlo', 'Bruno', 'Nikola', 'Leon', 'Mario', 'Toni'];
const SURNAMES = ['Horvat', 'Kovač', 'Babić', 'Marić', 'Jurić', 'Novak', 'Knežević', 'Vuković', 'Perić', 'Pavlović', 'Božić', 'Grgić'];

export function fighterFromState(state, name = 'Ti') {
  const levels = {};
  for (const m of MOVES) {
    const lvl = effectiveLevel(state, m.id);
    if (lvl > 0) levels[m.id] = lvl;
  }
  return { name, belt: state.belt, levels };
}

export function makeOpponent(belt, rng) {
  const bi = BELTS.indexOf(belt);
  const levels = {};
  for (const m of MOVES) {
    const mi = BELTS.indexOf(m.belt);
    if (mi <= bi && rng() < 0.8) levels[m.id] = Math.min(10, 1 + bi * 2 + Math.floor(rng() * 3));
    else if (mi === bi + 1 && rng() < 0.1) levels[m.id] = 1;
  }
  return { name: `${pick(rng, NAMES)} ${pick(rng, SURNAMES)}`, belt, levels };
}
